import sys

def next_tolerable_string(n, p, s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'[:p]
    s_list = list(s)

    for i in range(n - 1, -1, -1):
        current_index = alphabet.index(s_list[i])
        if current_index < p - 1:
            next_char = alphabet[current_index + 1]
            s_list[i] = next_char

            # Check if the new string is tolerable
            if i > 0 and s_list[i] == s_list[i - 1]:
                continue
            if i > 1 and s_list[i] == s_list[i - 2]:
                continue

            # Fill the rest of the string with the smallest possible characters
            for j in range(i + 1, n):
                for char in alphabet:
                    if (j > 0 and char != s_list[j - 1]) and (j > 1 and char != s_list[j - 2]):
                        s_list[j] = char
                        break

            return ''.join(s_list)

    return "NO"

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    p = int(input[1])
    s = input[2]
    result = next_tolerable_string(n, p, s)
    print(result)

if __name__ == "__main__":
    main()
